import random, json
from app import plan, resume
random.seed(7)
def find(trials):
    for trial in range(trials):
        w=random.randint(2,4); h=random.randint(2,4)
        cells=[(x,y) for y in range(h) for x in range(w)]
        s=random.choice(cells); g=random.choice(cells)
        blocked={c for c in cells if c not in (s,g) and random.random()<0.2}
        costs=[[random.randint(1,5) for _ in range(w)] for _ in range(h)]
        cap=random.randint(0,w+h+1)
        kw=dict(costs=costs,max_steps=cap)
        total=plan(w,h,blocked,s,g,trace=True,**kw)
        n=total["expanded"]
        for b in range(1,max(2,n+2)):
            first=plan(w,h,blocked,s,g,trace=True,max_expanded=b,snapshot=True,**kw)
            if first["status"]!="budget_exhausted": continue
            cp=json.loads(json.dumps(first["checkpoint"]))
            for bb in (b,b+1,n+3):
                a=resume(cp,max_expanded=bb)
                if a["status"]=="budget_exhausted":
                    try: resume(a["checkpoint"])
                    except ValueError as e:
                        return (w,h,sorted(blocked),s,g,costs,cap,b,bb,str(e),a["checkpoint"]["state"])
print(find(1500))
